    check("missing method exits 2", r.status === 2, `status=${r.status}`);
    check("missing method message", /Missing API method/.test(r.stderr), r.stderr);

    // 3. missing token
    r = run(port, ["chat.postMessage"], { SLACK_TOKEN: "" });
    check("missing token exits 2", r.status === 2, `status=${r.status}`);
    check("missing token message", /No token/.test(r.stderr), r.stderr);

    // 4. postMessage success
    r = run(port, ["chat.postMessage", "--channel", "C123", "--text", "hi"]);
    check("postMessage exits 0", r.status === 0, `status=${r.status} stderr=${r.stderr}`);
    check("postMessage summary", /Success: channel=C123, ts=1712345678\.123456/.test(r.stdout), r.stdout);
    const pm = calls.find((c) => c.url === "/chat.postMessage");
    check("postMessage auth header", pm && pm.auth === "Bearer test-token", JSON.stringify(pm));
    check("postMessage form-encoded", pm && pm.ctype.includes("application/x-www-form-urlencoded"), pm && pm.ctype);
    check("postMessage params sent", pm && pm.body.includes("text=hi") && pm.body.includes("channel=C123"), pm && pm.body);

    // 5. Slack error path (missing_scope with needed)
    r = run(port, ["chat.delete", "--channel", "C1", "--ts", "1.2"]);
    check("api error exits 1", r.status === 1, `status=${r.status}`);
    check("api error message", /missing_scope/.test(r.stderr) && /chat:write/.test(r.stderr), r.stderr);

    // 6. rate limit
    r = run(port, ["rate.limited"]);
    check("rate limited exits 3", r.status === 3, `status=${r.status}`);
    check("rate limit message", /Retry after 7/.test(r.stderr), r.stderr);

    // 7. pagination
    r = run(port, ["conversations.list", "--paginate"]);
    check("pagination exits 0", r.status === 0, `status=${r.status}`);
    check("pagination merged 3 items", /channels: 3 item\(s\)/.test(r.stdout), r.stdout);
    const listCalls = calls.filter((c) => c.url === "/conversations.list");
    check("pagination made 2 requests", listCalls.length === 2, `count=${listCalls.length}`);
    check("pagination sent cursor", listCalls.length === 2 && listCalls[1].body.includes("cursor=xyz"), JSON.stringify(listCalls));

    // 8. file upload (multipart)
    r = run(port, ["files.upload", "--filename", "notes.txt", "--file", UPLOAD_FIXTURE, "--channels", "C123"]);
    check("upload exits 0", r.status === 0, `status=${r.status} stderr=${r.stderr}`);
    check("upload summary", /file_id=F1/.test(r.stdout), r.stdout);
    const up = calls.find((c) => c.url === "/files.upload");
    check("upload multipart", up && up.ctype.includes("multipart/form-data"), up && up.ctype);
    check("upload contains filename", up && up.body.includes("notes.txt"), up && up.body.slice(0, 300));

    // 9. raw JSON body
    r = run(port, ["json.method", "--json", '{"a":1,"blocks":[{"type":"section"}]}']);
    check("json exits 0", r.status === 0, `status=${r.status} stderr=${r.stderr}`);
    check("json body sent", r.stdout.includes('"a": 1'), r.stdout);
    const jm = calls.find((c) => c.url === "/json.method");
    check("json content-type", jm && jm.ctype.includes("application/json"), jm && jm.ctype);

    // 10. invalid json
    r = run(port, ["chat.postMessage", "--json", "{not json"]);
    check("invalid json exits 2", r.status === 2, `status=${r.status}`);
    check("invalid json message", /not valid JSON/.test(r.stderr), r.stderr);
  } finally {
    server.close();
    try { fs.unlinkSync(UPLOAD_FIXTURE); } catch {}
  }
  console.log(`\n${passed} passed, ${failed} failed`);
  process.exit(failed ? 1 : 0);
})().catch((e) => { console.error(e); process.exit(1); });

#!/usr/bin/env node
"use strict";

/* Task-local packager for the slack-api skill.
 * Validates the skill (frontmatter, naming, references, no TODOs), then writes
 * a zip-format .skill file (store method, no external dependencies) and
 * verifies the archive by reading it back. */

const fs = require("node:fs");
const path = require("node:path");

function fail(msg) { console.error(`Validation failed: ${msg}`); process.exit(1); }

function validate(skillDir) {
  const skillName = path.basename(skillDir);
  if (!/^[a-z0-9-]+$/.test(skillName)) fail(`folder name "${skillName}" must be lowercase letters, digits, and hyphens only`);
  const skPath = path.join(skillDir, "SKILL.md");
  if (!fs.existsSync(skPath)) fail("SKILL.md missing");
  const content = fs.readFileSync(skPath, "utf8");
  const fm = content.match(/^---\r?\n([\s\S]*?)\r?\n---/);
  if (!fm) fail("SKILL.md missing YAML frontmatter");
  const fmText = fm[1];
  const name = fmText.match(/^name:\s*(.+)$/m)?.[1]?.trim();
  const desc = fmText.match(/^description:\s*(.+)$/m)?.[1]?.trim();
  if (!name) fail("frontmatter missing name");
  if (!desc) fail("frontmatter missing description");
  if (name !== skillName) fail(`frontmatter name "${name}" does not match folder name "${skillName}"`);
  if (desc.includes("\n")) fail("description must be a single-line string");
  const keys = [...fmText.matchAll(/^([a-zA-Z_-]+):/gm)].map((m) => m[1]);
  const extra = keys.filter((k) => !["name", "description"].includes(k));
  if (extra.length) fail(`unexpected frontmatter fields: ${extra.join(", ")}`);
  if (/TODO/i.test(content)) fail("SKILL.md still contains TODO placeholders");
  const refs = [...content.matchAll(/\]\(([^)#]+)\)/g)].map((m) => m[1]);
  for (const ref of refs) {
    if (/^https?:|^#/.test(ref)) continue;
    if (!fs.existsSync(path.join(skillDir, ref))) fail(`referenced file missing: ${ref}`);
  }
  console.log(`Validation passed for "${skillName}"`);
}

function crc32(buf) {
  const table = crc32.table || (crc32.table = (() => {
    const t = new Array(256);
    for (let n = 0; n < 256; n++) {
      let c = n;
      for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
      t[n] = c >>> 0;
    }
    return t;
  })());
  let crc = 0xffffffff;
  for (let i = 0; i < buf.length; i++) crc = (crc >>> 8) ^ table[(crc ^ buf[i]) & 0xff];
  return (crc ^ 0xffffffff) >>> 0;
}

function dosDateTime(d = new Date()) {
  return {
    time: (d.getHours() << 11) | (d.getMinutes() << 5) | (d.getSeconds() >> 1),
    date: (((d.getFullYear() - 1980) & 0x7f) << 9) | ((d.getMonth() + 1) << 5) | d.getDate(),
  };
}

function collectFiles(dir, base) {
  const out = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    const rel = path.join(base, entry.name).split(path.sep).join("/");
    if (entry.isDirectory()) out.push(...collectFiles(full, rel));
    else out.push({ rel, full });
  }
  return out.sort((a, b) => (a.rel < b.rel ? -1 : 1));
}

function buildZip(files) {
  const chunks = [];
  const central = [];
  let offset = 0;
  const now = dosDateTime();
  for (const f of files) {
    const data = fs.readFileSync(f.full);
    const nameBuf = Buffer.from(f.rel, "utf8");
    const crc = crc32(data);
    const local = Buffer.alloc(30);
    local.writeUInt32LE(0x04034b50, 0);
    local.writeUInt16LE(20, 4);            // version needed
    local.writeUInt16LE(0x0800, 6);        // UTF-8 flag
    local.writeUInt16LE(0, 8);             // method: store
    local.writeUInt16LE(now.time, 10);
    local.writeUInt16LE(now.date, 12);
    local.writeUInt32LE(crc, 14);
    local.writeUInt32LE(data.length, 18);
    local.writeUInt32LE(data.length, 22);
    local.writeUInt16LE(nameBuf.length, 26);
    local.writeUInt16LE(0, 28);
    chunks.push(local, nameBuf, data);
    const cd = Buffer.alloc(46);
    cd.writeUInt32LE(0x02014b50, 0);
    cd.writeUInt16LE(0x031e, 4);           // made by: Unix, v3.0
    cd.writeUInt16LE(20, 6);               // version needed
    cd.writeUInt16LE(0x0800, 8);           // UTF-8 flag
    cd.writeUInt16LE(0, 10);               // method: store
    cd.writeUInt16LE(now.time, 12);
    cd.writeUInt16LE(now.date, 14);
    cd.writeUInt32LE(crc, 16);
    cd.writeUInt32LE(data.length, 20);
    cd.writeUInt32LE(data.length, 24);
    cd.writeUInt16LE(nameBuf.length, 28);
    cd.writeUInt16LE(0, 30);
    cd.writeUInt16LE(0, 32);
    cd.writeUInt16LE(0, 34);
    cd.writeUInt16LE(0, 36);
    cd.writeUInt32LE(0o100644 << 16, 38);  // external attrs: regular file
    cd.writeUInt32LE(offset, 42);
    central.push({ buf: cd, name: nameBuf });
    offset += local.length + nameBuf.length + data.length;
  }
  const cdStart = offset;
  const cdSize = central.reduce((s, c) => s + c.buf.length + c.name.length, 0);
  for (const c of central) chunks.push(c.buf, c.name);
  const eocd = Buffer.alloc(22);
  eocd.writeUInt32LE(0x06054b50, 0);
  eocd.writeUInt16LE(0, 4);
  eocd.writeUInt16LE(0, 6);
  eocd.writeUInt16LE(central.length, 8);
  eocd.writeUInt16LE(central.length, 10);
  eocd.writeUInt32LE(cdSize, 12);
  eocd.writeUInt32LE(cdStart, 16);
  eocd.writeUInt16LE(0, 20);
  chunks.push(eocd);
  return Buffer.concat(chunks);
}

function verifyZip(buf, expectedNames) {
  const eocd = buf.slice(buf.length - 22);
  if (eocd.readUInt32LE(0) !== 0x06054b50) throw new Error("bad end-of-central-directory record");
  const count = eocd.readUInt16LE(10);
  let p = eocd.readUInt32LE(16);
  const names = [];
  for (let i = 0; i < count; i++) {
    if (buf.readUInt32LE(p) !== 0x02014b50) throw new Error(`bad central directory header at ${p}`);
    const nameLen = buf.readUInt16LE(p + 28);
    names.push(buf.slice(p + 46, p + 46 + nameLen).toString("utf8"));
    p += 46 + nameLen + buf.readUInt16LE(p + 30) + buf.readUInt16LE(p + 32);
  }
  const missing = expectedNames.filter((n) => !names.includes(n));
  if (missing.length) throw new Error(`missing entries: ${missing.join(", ")}`);
  return names;
}

const skillDir = path.resolve(process.argv[2] || "slack-api");
const outDir = path.resolve(process.argv[3] || "dist");
const skillName = path.basename(skillDir);

validate(skillDir);
const files = collectFiles(skillDir, skillName);
const zip = buildZip(files);
fs.mkdirSync(outDir, { recursive: true });
const outPath = path.join(outDir, `${skillName}.skill`);
fs.writeFileSync(outPath, zip);
const verified = verifyZip(zip, files.map((f) => f.rel));
console.log(`Packaged ${outPath}`);
console.log(`Entries (${verified.length}):`);
for (const v of verified) console.log(`  ${v}`);
console.log(`Size: ${zip.length} bytes`);

#!/usr/bin/env node
"use strict";

/*
 * slack_api.cjs — dependency-free Slack Web API client (Node 18+).
 *
 * Usage:
 *   node slack_api.cjs <method> [--key value ...] [options]
 *
 * Examples:
 *   node slack_api.cjs chat.postMessage --channel C123456 --text "Hello from Slack API skill"
 *   node slack_api.cjs conversations.history --channel C123456 --limit 20
 *   node slack_api.cjs conversations.list --types public_channel --paginate 5
 *   node slack_api.cjs files.upload --filename notes.txt --file ./notes.txt --channels C123456
 *   node slack_api.cjs chat.postMessage --json '{"channel":"C123456","blocks":[...]}'
 *
 * Options:
 *   --token <token>   Bot/user token; defaults to $SLACK_TOKEN
 *   --json <json>     Send a raw JSON body instead of form-encoded key/value params
 *   --file <path>     Attach a file via multipart/form-data (for files.upload)
 *   --paginate [n]    Follow response_metadata.next_cursor for up to n pages (default 10)
 *   --raw             Print the complete JSON response (default output is summarized/truncated)
 *   --help            Show this help
 *
 * Exit codes: 0 success, 1 Slack/API error, 2 usage/config error, 3 rate-limited.
 */

const MAX_PRINT = 8000;

const HELP = `slack_api.cjs — Slack Web API client

Usage:
  node slack_api.cjs <method> [--key value ...] [options]

Examples:
  node slack_api.cjs chat.postMessage --channel C123456 --text "Hello"
  node slack_api.cjs conversations.history --channel C123456 --limit 20
  node slack_api.cjs conversations.list --types public_channel --paginate 5
  node slack_api.cjs files.upload --filename notes.txt --file ./notes.txt --channels C123456
  node slack_api.cjs chat.postMessage --json '{"channel":"C123456","text":"Hi"}'

Options:
  --token <token>   Bot/user token; defaults to $SLACK_TOKEN
  --json <json>     Send a raw JSON body instead of form-encoded params
  --file <path>     Attach a file via multipart/form-data (for files.upload)
  --paginate [n]    Follow next_cursor for up to n pages (default 10)
  --raw             Print the full JSON response (output is summarized/truncated otherwise)
  --help            Show this help

Notes:
  - Pass comma-separated values for list params (e.g. --users U1,U2, --types public_channel,private_channel).
  - Exit codes: 0 success, 1 Slack/API error, 2 usage/config error, 3 rate-limited.`;

class CliError extends Error {
  constructor(message, exitCode = 1) {
    super(message);
    this.exitCode = exitCode;
  }
}

function parseArgs(argv) {
  const args = { method: null, params: {}, token: null, json: null, file: null, raw: false, paginate: 0, help: false };
  const take = (i, flag) => {
    const v = argv[i + 1];
    if (v === undefined || v.startsWith("--")) throw new CliError(`Missing value for ${flag}. See --help.`, 2);
    return v;
  };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === "--help" || a === "-h") args.help = true;
    else if (a === "--token") args.token = take(i++, "--token");
    else if (a === "--json") args.json = take(i++, "--json");
    else if (a === "--file") args.file = take(i++, "--file");
    else if (a === "--raw") args.raw = true;
    else if (a === "--paginate") {
      const next = argv[i + 1];
      if (next !== undefined && /^\d+$/.test(next)) { args.paginate = parseInt(next, 10); i++; }
      else args.paginate = 10;
    }
    else if (a.startsWith("--")) args.params[a.slice(2)] = take(i++, a);
    else if (args.method === null) args.method = a;
    else throw new CliError(`Unexpected positional argument "${a}". See --help.`, 2);
  }
  return args;
}

function summarize(data) {
  if (!data) return "empty response";
  if (data.ok === false) return `Slack error: ${data.error}`;
  const parts = [];
  for (const key of ["channel", "ts", "message_ts", "user", "id", "name", "email"]) {
    const v = data[key];
    if (v !== undefined && (typeof v === "string" || typeof v === "number")) parts.push(`${key}=${v}`);
  }
  if (data.channel && typeof data.channel === "object" && data.channel.id) parts.push(`channel_id=${data.channel.id}`);
  if (data.file && typeof data.file === "object" && data.file.id) parts.push(`file_id=${data.file.id}`);
  if (parts.length > 0) return parts.join(", ");
  const arrKey = Object.keys(data).find((k) => Array.isArray(data[k]));
  if (arrKey) return `${arrKey}: ${data[arrKey].length} item(s)`;
  return "ok";
}

function printResult(data, raw, sink = process.stdout) {
  const json = JSON.stringify(data, null, 2);
  if (raw) { sink.write(json + "\n"); return; }
  sink.write(`Success: ${summarize(data)}\n`);
  if (json.length > MAX_PRINT) {
    sink.write(json.slice(0, MAX_PRINT) + `\n... [truncated at ${MAX_PRINT} chars; re-run with --raw for the full response]\n`);
  } else {
    sink.write(json + "\n");
  }
}

function mergePages(pages) {
  const merged = { ...pages[0] };
  const arrKey = Object.keys(pages[0]).find((k) => Array.isArray(pages[0][k]));
  if (arrKey && pages.length > 1) {
    merged[arrKey] = pages.flatMap((p) => (p[arrKey] ? p[arrKey] : []));
  }
  delete merged.response_metadata;
  return merged;
}

async function run(argv, env = process.env) {
  const args = parseArgs(argv);
  if (args.help) return { help: true };
  if (!args.method) throw new CliError("Missing API method (e.g. chat.postMessage). See --help.", 2);
  const token = args.token || env.SLACK_TOKEN;
  if (!token) throw new CliError("No token found. Pass --token <token> or set the SLACK_TOKEN environment variable.", 2);
  if (args.paginate > 0 && (args.json || args.file)) throw new CliError("--paginate cannot be combined with --json or --file.", 2);
  if (args.json) {
    try { JSON.parse(args.json); } catch { throw new CliError("--json value is not valid JSON.", 2); }
  }
  const base = env.SLACK_API_BASE || "https://slack.com/api";

  const call = async (method, params) => {
    const headers = { Authorization: `Bearer ${token}` };
    let body;
    if (args.file) {
      const fs = require("node:fs");
      const path = require("node:path");
      const fd = new FormData();
      fd.append("file", new Blob([fs.readFileSync(args.file)]), path.basename(args.file));
      for (const [k, v] of Object.entries(params)) fd.append(k, String(v));
      body = fd;
    } else if (args.json) {
      headers["Content-Type"] = "application/json";
      body = args.json;
    } else {
      headers["Content-Type"] = "application/x-www-form-urlencoded";
      body = new URLSearchParams(params).toString();
    }
    let resp;
    try {
      resp = await fetch(`${base}/${method}`, { method: "POST", headers, body, signal: AbortSignal.timeout(60000) });
    } catch (err) {
      throw new CliError(`Request failed: ${err.message}`, 1);
    }
    const data = await resp.json().catch(() => null);
    if (resp.status === 429) throw new CliError(`Rate limited (HTTP 429). Retry after ${resp.headers.get("retry-after") || "?"} seconds.`, 3);
    if (!data || data.ok === false) {
      const code = data && data.error ? data.error : `HTTP ${resp.status}`;
      const needed = data && data.needed ? ` Needed scope(s): ${data.needed}.` : "";
      throw new CliError(`Slack API error: ${code}.${needed}`, 1);
    }
    return data;
  };

  if (args.paginate > 0) {
    const pages = [];
    let cursor = args.params.cursor || null;
    for (let i = 0; i < args.paginate; i++) {
      const params = { ...args.params };
      if (cursor) params.cursor = cursor;
      const data = await call(args.method, params);
      pages.push(data);
      cursor = data.response_metadata && data.response_metadata.next_cursor ? data.response_metadata.next_cursor : null;
      if (!cursor) break;
    }
    const merged = mergePages(pages);
    if (cursor) merged._pagination_note = `Stopped after ${args.paginate} page(s); more results exist (next_cursor=${cursor}). Increase --paginate or pass --cursor.`;
    return { data: merged, raw: args.raw };
  }
  return { data: await call(args.method, args.params), raw: args.raw };
}

if (require.main === module) {
  (async () => {
    try {
      const out = await run(process.argv.slice(2));
      if (out.help) { process.stdout.write(HELP + "\n"); process.exit(0); }
      printResult(out.data, out.raw);
    } catch (err) {
      console.error(`Error: ${err.message}`);
      process.exit(err instanceof CliError ? err.exitCode : 1);
    }
  })();
}

module.exports = { run, parseArgs, summarize, mergePages, printResult, CliError, HELP };

#!/usr/bin/env node
"use strict";

/* Task-local test harness for slack-api/scripts/slack_api.cjs.
 * - CLI wrapper behaviors are tested by spawning the script (no network needed).
 * - API request/response paths are tested in-process against a local mock
 *   Slack server (spawned children cannot use the network in this sandbox). */

const http = require("node:http");
const os = require("node:os");
const fs = require("node:fs");
const path = require("node:path");
const { spawnSync } = require("node:child_process");

const CLIENT = path.join(__dirname, "slack-api", "scripts", "slack_api.cjs");
const UPLOAD_FIXTURE = path.join(os.tmpdir(), "slack-skill-upload-fixture.txt");

let passed = 0;
let failed = 0;

function check(name, cond, detail) {
  if (cond) { passed++; console.log(`PASS ${name}`); }
  else { failed++; console.log(`FAIL ${name}${detail ? ` — ${detail}` : ""}`); }
}

function startServer() {
  const calls = [];
  const server = http.createServer((req, res) => {
    const chunks = [];
    req.on("data", (c) => chunks.push(c));
    req.on("end", () => {
      const body = Buffer.concat(chunks);
      const record = {
        method: req.method,
        url: req.url,
        auth: req.headers.authorization || "",
        ctype: req.headers["content-type"] || "",
        body: body.toString("utf8"),
      };
      calls.push(record);
      const route = req.url.split("?")[0];
      let status = 200;
      let payload = { ok: false, error: "unknown_route" };
      if (route === "/ping") {
        payload = { ok: true };
      } else if (route === "/chat.postMessage") {
        payload = record.auth === "Bearer test-token"
          ? { ok: true, channel: "C123", ts: "1712345678.123456" }
          : { ok: false, error: "invalid_auth" };
      } else if (route === "/conversations.list") {
        const hasCursor = /(^|&)cursor=xyz(&|$)/.test(record.body);
        payload = hasCursor
          ? { ok: true, channels: [{ id: "C3", name: "third" }], response_metadata: { next_cursor: "" } }
          : { ok: true, channels: [{ id: "C1", name: "one" }, { id: "C2", name: "two" }], response_metadata: { next_cursor: "xyz" } };
      } else if (route === "/files.upload") {
        payload = { ok: true, file: { id: "F1", name: "notes.txt" } };
      } else if (route === "/chat.delete") {
        payload = { ok: false, error: "missing_scope", needed: "chat:write", provided: "channels:read" };
      } else if (route === "/rate.limited") {
        status = 429;
        res.setHeader("Retry-After", "7");
        payload = { ok: false, error: "rate_limited" };
      } else if (route === "/json.method") {
        payload = { ok: true, echo: JSON.parse(record.body), ctype: record.ctype };
      }
      res.writeHead(status, { "Content-Type": "application/json" });
      res.end(JSON.stringify(payload));
    });
  });
  return new Promise((resolve) => {
    server.listen(0, "127.0.0.1", () => resolve({ server, calls, port: server.address().port }));
  });
}

function spawnCli(args, envOverrides = {}) {
  return spawnSync(process.execPath, [CLIENT, ...args], {
    encoding: "utf8",
    env: { ...process.env, SLACK_TOKEN: "test-token", ...envOverrides },
  });
}

async function expectCliError(client, args, code, messagePattern) {
  try {
    await client.run(args);
    check(`run(${args[0]}) throws with exit code ${code}`, false, "expected CliError but run succeeded");
  } catch (err) {
    check(`run(${args[0]}) exit code ${code}`, err.exitCode === code, `got ${err.exitCode}: ${err.message}`);
    check(`run(${args[0]}) message`, messagePattern.test(err.message), err.message);
  }
}

(async () => {
  fs.writeFileSync(UPLOAD_FIXTURE, "hello from the slack skill test\n");
  const { server, calls, port } = await startServer();
  try {
    // ---------- CLI wrapper (spawned, no network) ----------
    let r = spawnCli(["--help"]);
    check("cli help exits 0", r.status === 0, `status=${r.status}`);
    check("cli help prints usage", /Usage:/.test(r.stdout), r.stdout.slice(0, 200));

    r = spawnCli([]);
